from pathlib import Path
import subprocess


def git(*arguments):
    return subprocess.check_output(["git", *arguments], text=True)


def namespace(source, label):
    result = {}
    exec(compile(source, label, "exec"), result)
    return result


def changed_lines(*arguments):
    return [line for line in git("diff", "--no-ext-diff", "--unified=0", *arguments).splitlines()
            if line.startswith(("+", "-")) and not line.startswith(("+++", "---"))]


committed = namespace(git("show", "HEAD:app.py"), "committed:app.py")
indexed = namespace(git("show", ":app.py"), "indexed:app.py")
working = namespace(Path("app.py").read_text(), "working:app.py")
assert (committed["APP_TITLE"], committed["APP_LOCALE"]) == ("orders", "en")
assert (indexed["APP_TITLE"], indexed["APP_LOCALE"]) == ("orders", "ru")
assert (working["APP_TITLE"], working["APP_LOCALE"]) == ("warehouse", "ru")
for version in [committed, indexed, working]:
    for value, expected in [(0, "USD 0.00"), (1, "USD 0.01"), (-101, "USD -1.01"), (12345, "USD 123.45")]:
        assert version["format_total"](value) == expected
assert git("rev-list", "--count", "HEAD").strip() == "2"
changed = set(git("diff-tree", "--no-commit-id", "--name-only", "-r", "HEAD").splitlines())
assert changed and changed <= {"app.py", "test_app.py"}
assert git("diff", "--cached", "--name-only").splitlines() == ["app.py"]
assert git("diff", "--name-only").splitlines() == ["app.py"]
assert changed_lines("--cached") == ['-APP_LOCALE = "en"', '+APP_LOCALE = "ru"']
assert changed_lines() == ['-APP_TITLE = "orders"', '+APP_TITLE = "warehouse"']
